def ensure_first_token_map(spec, tokenizer):
    if spec.entity_type_first_token:
        return
    for etype in spec.entity_types:
        token_ids = tokenizer.encode(etype, add_special_tokens=False)
        spec.entity_type_token_ids[etype] = token_ids
        spec.entity_type_first_token[etype] = token_ids[0]
    for etype in spec.event_types:
        token_ids = tokenizer.encode(etype, add_special_tokens=False)
        spec.event_type_token_ids[etype] = token_ids
        spec.event_type_first_token[etype] = token_ids[0]
    for role in spec.all_roles:
        token_ids = tokenizer.encode(role, add_special_tokens=False)
        spec.role_token_ids[role] = token_ids
        spec.role_first_token[role] = token_ids[0]


